    '{n} nouveau(x) skin(s) · {d} doublon(s), remboursé(s) {c} 💀': ['{n} new skin(s) · {d} duplicate(s), refunded {c} 💀', '{n} skin(s) nuevo(s) · {d} repetido(s), reembolsado(s) {c} 💀'],
